import { useState, useEffect } from "react";
import axios from "axios";

const ImageUpload = () => {
  const [sliderImages, setSliderImages] = useState([]);
  const [bigPhotoImages, setBigPhotoImages] = useState([]);
  const [allPhotos, setAllPhotos] = useState([]);
  const [uploadedImages, setUploadedImages] = useState>({
    slider: [],
    bigphoto: [],
    allphoto: [],
  });

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    try {
      const response = await axios.get("http://localhost:5000/images");
      setUploadedImages(response.data);
    } catch (error) {
      console.error("Error fetching images:", error);
    }
  };

  const handleFileChange = (e, type) => {
    if (e.target.files) {
      const filesArray = Array.from(e.target.files);
      if (type === "slider") setSliderImages(filesArray);
      else if (type === "bigphoto") setBigPhotoImages(filesArray);
      else if (type === "allphoto") setAllPhotos(filesArray);
    }
  };

  const handleUpload = async () => {
    const formData = new FormData();
    sliderImages.forEach((file) => formData.append("slider", file));
    bigPhotoImages.forEach((file) => formData.append("bigphoto", file));
    allPhotos.forEach((file) => formData.append("allphoto", file));

    try {
      const response = await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      console.log("Upload success:", response.data);
      fetchImages(); // Refresh images after upload
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  return (
    <div>
      <h3>Upload Images</h3>
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "slider")} />
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "bigphoto")} />
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "allphoto")} />
      <button onClick={handleUpload}>Upload</button>

      <h3>Uploaded Images</h3>
      <div>
        <h4>Slider Images</h4>
        {uploadedImages.slider.map((image, index) => (
          <img key={index} src={image.url} alt={image.filename} width="100" />
        ))}

        <h4>Big Photos</h4>
        {uploadedImages.bigphoto.map((image, index) => (
          <img key={index} src={image.url} alt={image.filename} width="100" />
        ))}

        <h4>All Photos</h4>
        {uploadedImages.allphoto.map((image, index) => (
          <img key={index} src={image.url} alt={image.filename} width="100" />
        ))}
      </div>
    </div>
  );
};

export default ImageUpload;
